function tau_M_ref = mfun_imfvc_torque_reference(standby, tau_M_ref_in, p)
%MFUN_IMFVC_TORQUE_REFERENCE Block torque_reference of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN).
% The external torque reference, zero in standby
tau_M_ref = tau_M_ref_in;
if standby ~= 0
    tau_M_ref = 0;
end
end
